-- Generated by drizzle-kit, then checked. IDEMPOTENT: runs on every container start.
-- Lifetime stats (api/ROUTES.md "Lifetime stats"): non-personal per-society,
-- per-IST-day counts that survive the 3-year purge of personal data. Counts
-- only, no user ids or text. No FK on society_id on purpose. The worker's
-- hourly rollup backfills it from existing data on its first run.
CREATE TABLE IF NOT EXISTS "platform_stats_daily" (
	"day" date NOT NULL,
	"society_id" uuid NOT NULL,
	"bookings_created" integer DEFAULT 0 NOT NULL,
	"bookings_completed" integer DEFAULT 0 NOT NULL,
	"disputes_raised" integer DEFAULT 0 NOT NULL,
	"listings_created" integer DEFAULT 0 NOT NULL,
	"listings_active" integer,
	"members" integer,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "platform_stats_daily_pk" PRIMARY KEY("day","society_id")
);
